             />
             <p class="helper" id="${id}-helper">${helperText}</p>
             <p class="error" id="${id}-error">${error || ""}</p>
           </div>
         `;
       }

       function escapeHtml(value) {
         return String(value)
           .replaceAll("&", "&amp;")
           .replaceAll("<", "&lt;")
           .replaceAll(">", "&gt;")
           .replaceAll('"', "&quot;")
           .replaceAll("'", "&#39;");
       }

       function render() {
         const errors = validate(state.values);
         const showErrors = state.submitted || state.touched.fullName || state.touched.email || state.touched.phone;
         const statusMessage = state.submittedSuccessfully
           ? "Thanks — your support request is ready to send."
           : "";

         document.getElementById("app").innerHTML = `
           <main class="page">
             <section class="card" aria-labelledby="support-title">
               <div class="hero">
                 <span class="eyebrow">Support</span>
                 <h1 id="support-title">Contact our team</h1>
                 <p class="subtitle">
                   Share the details below and we&apos;ll route your message to the right person.
                 </p>
               </div>

               <form id="support-form" novalidate>
                 <div class="grid">
                   ${fieldMarkup({
                     id: "fullName",
                     label: "Full name",
                     type: "text",
                     placeholder: "Jane Doe",
                     required: true,
                     helperText: helpers.fullName,
                     value: state.values.fullName,
                     error: showErrors ? errors.fullName : "",
                   })}
                   ${fieldMarkup({
                     id: "email",
                     label: "Email address",
                     type: "email",
                     placeholder: "jane@company.com",
                     required: true,
                     helperText: helpers.email,
                     value: state.values.email,
                     error: showErrors ? errors.email : "",
                   })}
                   ${fieldMarkup({
                     id: "phone",
                     label: "Phone number",
                     type: "tel",
                     placeholder: "+1 (555) 123-4567",
